-- Post-check: every calculator exists once, with all its fields; every Die Casting
-- catalog row named like a process calculator points at it.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Die Casting - Net Material Usage$q$, 3),
    ($q$Die Casting - Gross Material Usage$q$, 4),
    ($q$Die Casting - Shot Volume$q$, 13),
    ($q$Die Casting - Clamp Force$q$, 5),
    ($q$Die Casting - High Pressure Die Casting$q$, 23),
    ($q$Die Casting - Gravity Die Casting$q$, 26),
    ($q$Die Casting - Melting$q$, 11),
    ($q$Die Casting - Trim$q$, 3),
    ($q$Die Casting - Trim Force$q$, 4),
    ($q$Die Casting - Finishing$q$, 21),
    ($q$Die Casting - Cleaning$q$, 6),
    ($q$Die Casting - Visual Inspection$q$, 3),
    ($q$Die Casting - Coremaking$q$, 3),
    ($q$Die Casting - Core Sand$q$, 6),
    ($q$Die Casting - Core Refractory Coat$q$, 4),
    ($q$Die Casting - Refractory Coat Air Dry$q$, 9),
    ($q$Die Casting - Refractory Coat Oven Dry$q$, 10),
    ($q$Die Casting - Slide$q$, 15),
    ($q$Die Casting - Die Size$q$, 12),
    ($q$Die Casting - Die Build$q$, 49),
    ($q$Die Casting - Die Cost$q$, 20),
    ($q$Die Casting - Die Life$q$, 10),
    ($q$Die Casting - Corebox$q$, 11)
  ) AS e(name, field_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 893: calculators incomplete: %', bad;
  END IF;

  SELECT string_agg(m.operation, ', ') INTO bad
  FROM public.process_calculator_mappings m
  WHERE m.process_group = 'Die Casting'
    AND m.operation IN ($q$Shot Volume$q$, $q$Clamp Force$q$, $q$High Pressure Die Casting$q$, $q$Gravity Die Casting$q$, $q$Melting$q$, $q$Trim$q$, $q$Trim Force$q$, $q$Finishing$q$, $q$Cleaning$q$, $q$Visual Inspection$q$, $q$Coremaking$q$, $q$Core Sand$q$, $q$Core Refractory Coat$q$, $q$Refractory Coat Air Dry$q$, $q$Refractory Coat Oven Dry$q$)
    AND m.calculator_id IS NULL;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 893: Die Casting catalog rows without a calculator: %', bad;
  END IF;
END
$post$;

COMMIT;

NOTIFY pgrst, 'reload schema';
